// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;

import java.util.HashMap;
import java.util.Map;

import org.junit.jupiter.api.Test;

class TripleComponentRoleEqualityTest {
	@Test
	void componentRoleParticipatesInEqualityAndHashBasedCollections() {
		TripleComponent subject = new TripleComponent(new Var("triple"), TripleComponent.Role.SUBJECT);
		TripleComponent sameSubject = new TripleComponent(new Var("triple"), TripleComponent.Role.SUBJECT);
		TripleComponent object = new TripleComponent(new Var("triple"), TripleComponent.Role.OBJECT);

		assertEquals(subject, sameSubject);
		assertEquals(subject.hashCode(), sameSubject.hashCode());
		assertNotEquals(subject, object, "the extracted component role is part of query-expression identity");

		Map<TripleComponent, String> expressionsByRole = new HashMap<>();
		expressionsByRole.put(subject, "subject");
		expressionsByRole.put(object, "object");
		assertEquals(2, expressionsByRole.size());
		assertEquals("subject", expressionsByRole.get(subject));
		assertEquals("object", expressionsByRole.get(object));
	}
}
